import { createAppIdentity, addMembership, assignRole } from '@projexlight/sdk-persona';
const { app_identity_id } = await createAppIdentity({ person_id, app_id });
const { membership_id } = await addMembership({
  app_identity_id, tenant_id, bu_id: null,
});
await assignRole({ app_identity_id, role: 'owner', scope: { tenant_id } });

import { resolvePersona } from '@projexlight/sdk-persona';
const persona = await resolvePersona({
  person_id, app_id, tenant_id: switch_target_tenant,
});
const token = signJwt(buildClaims(persona));

import { putExtension } from '@projexlight/sdk-persona';
await putExtension({
  app_identity_id, domain: 'healthcare',
  payload: { npi: '1234567890', specialty: 'internal-medicine', dea: '...' },
});

import { offboardPersona } from '@projexlight/sdk-persona';
await offboardPersona({
  persona_id, reason: 'tech-transfer', offboarded_by_persona_id,
});
